#include <bits/stdc++.h>
using namespace std;
int N=40,gram[8],sr[128],gr[64];unsigned long long counts[41][4];long long leaves=0;
int rk(vector<int> a){int r=0;for(int b=2;b>=0;b--){int k=r;while(k<(int)a.size()&&!(a[k]>>b&1))k++;if(k==(int)a.size())continue;swap(a[k],a[r]);for(int j=r+1;j<(int)a.size();j++)if(a[j]>>b&1)a[j]^=a[r];r++;}return r;}
void rec(vector<int>&cy,int j,int sum,int g,int support){if(j==(int)cy.size()){if(sr[support]==3){for(int n=sum;n<=N;n++)counts[n][3-gr[g]]++;}leaves++;return;}int len=__builtin_popcount((unsigned)cy[j]),delta=0;for(int i=1;i<8;i++)if(cy[j]>>(i-1)&1)delta^=gram[i];for(int c=0;sum+c*len<=N;c++)rec(cy,j+1,sum+c*len,g^((c&1)?delta:0),support|(c?cy[j]:0));}
int main(){for(int i=1;i<8;i++){int idx=0;for(int a=0;a<3;a++)for(int b=a;b<3;b++){if((i>>a&1)&&(i>>b&1))gram[i]|=1<<idx;idx++;}}for(int s=0;s<128;s++){vector<int> a;for(int i=1;i<8;i++)if(s>>(i-1)&1)a.push_back(i);sr[s]=rk(a);}for(int g=0;g<64;g++){vector<int>a(3);int idx=0;for(int i=0;i<3;i++)for(int j=i;j<3;j++){if(g>>idx&1){a[i]|=1<<j;a[j]|=1<<i;}idx++;}gr[g]=rk(a);}int group=0;for(int a=1;a<8;a++)for(int b=1;b<8;b++)for(int c=1;c<8;c++){if(rk({a,b,c})<3)continue;group++;int p[8];for(int i=1;i<8;i++)p[i]=((i&1)?a:0)^((i&2)?b:0)^((i&4)?c:0);int seen=0;vector<int>cy;for(int i=1;i<8;i++)if(!(seen>>(i-1)&1)){int t=i,mask=0;do{mask|=1<<(t-1);t=p[t];}while(t!=i);cy.push_back(mask);seen|=mask;}rec(cy,0,0,0,0);}cerr<<"group "<<group<<" leaves "<<leaves<<"\n";for(int n=6;n<=N;n++){cout<<n;for(int h=0;h<4;h++){assert(counts[n][h]%group==0);cout<<" "<<counts[n][h]/group;}cout<<"\n";}}
